  ('ea28b186-88de-4b7c-acd2-b0151f88ca0c', 'C', 'misconception', 'conflating reuptake-for-recycling with vesicular release'),
  ('ea28b186-88de-4b7c-acd2-b0151f88ca0c', 'D', 'misconception', 'more transmitter reverses the sign of signaling');

